using OpenCvSharp;using SarmatVisionHold.KestrelClient.Control;using SarmatVisionHold.KestrelClient.Models;using SarmatVisionHold.KestrelClient.Networking;using SarmatVisionHold.Vision;
namespace SarmatVisionHold.KestrelClient.Output { public sealed class PreviewRenderer { public bool Vectors=true,Telemetry=true;
 public int Show(Mat frame,SparseOpticalFlowResult flow,MotionDecision d,GroundTruthMotion g,ValidationResult v,uint number,double time,double latency,double processing,SynchronizationCounters c,ConnectionState connection,VisionControlMode mode,VisionControlOutput control,double saturation){foreach(var t in flow.Tracks){var color=t.Accepted?Scalar.LimeGreen:Scalar.Red;Cv2.Circle(frame,(Point)t.From,2,color,-1);if(Vectors&&t.ForwardTracked)Cv2.ArrowedLine(frame,(Point)t.From,(Point)t.To,color,1,LineTypes.AntiAlias,0,.2);}Cv2.Rectangle(frame,new Rect(0,0,frame.Width,Telemetry?260:190),Scalar.Black,-1);Put(frame,$"#{number} t={time:F3}s net={latency:F1}ms proc={processing:F1}ms {connection}",20,Scalar.White);Put(frame,$"FLOW raw=({flow.TranslationX:F2},{flow.TranslationY:F2}) smooth=({d.SmoothedX:F2},{d.SmoothedY:F2}) rot={flow.RotationDegrees:F2} q={flow.Quality:F2}",44,Scalar.Yellow);Put(frame,$"CAM motion=({control.CameraMotionX:F1},{control.CameraMotionY:F1}) velErr=({control.ErrorX:F1},{control.ErrorY:F1})",68,Scalar.Yellow);Put(frame,$"HOLD pos=({control.PositionX:F2},{control.PositionY:F2}) posP=({control.PositionTermX:F3},{control.PositionTermY:F3})",92,Scalar.Yellow);Put(frame,$"CTRL {mode}/{control.State} P=({control.PTermX:F3},{control.PTermY:F3}) I=({control.ITermX:F3},{control.ITermY:F3}) D=({control.DTermX:F3},{control.DTermY:F3})",116,Scalar.Cyan);Put(frame,$"OUT raw=({control.RawRoll:F3},{control.RawPitch:F3}) clamp=({control.ClampedRoll:F3},{control.ClampedPitch:F3}) slew=({control.RollCommand:F3},{control.PitchCommand:F3})",140,Scalar.Cyan);Put(frame,$"ACK sent={control.SentSequence} applied={control.AppliedSequence} ok={control.Acknowledged} frozen={control.IntegratorFrozen} sat={saturation:F1}% reason={control.Reason??"-"}",164,control.Reason==null?Scalar.LimeGreen:Scalar.Orange);Put(frame,$"GT {g.Classification} {g.TextureDirection} rot={g.RotationDirection} VALIDATION {v.Status}",188,v.Status==ValidationStatus.PASS?Scalar.LimeGreen:v.Status==ValidationStatus.FAIL?Scalar.Red:Scalar.Orange);if(Telemetry){Put(frame,$"sync matched={c.Matched} unmatched={c.FrameWithoutTelemetry+c.TelemetryWithoutFrame} dup={c.DuplicateFrame+c.DuplicateTelemetry} order={c.OutOfOrder}",212,Scalar.White);Put(frame,"C diagnostics/control | O off | Q/Esc quit | Space pause | S snapshot | V vectors | T telemetry",236,Scalar.White);}Cv2.ImShow("Sarmat Vision Hold - Kestrel",frame);return Cv2.WaitKey(1);}
 static void Put(Mat m,string s,int y,Scalar color)=>Cv2.PutText(m,s,new Point(8,y),HersheyFonts.HersheySimplex,.43,color,1,LineTypes.AntiAlias);public void Close()=>Cv2.DestroyAllWindows();} }
